return function(C)
 C.expansion_text={["recasting"]={["es"]={["name"]="Cambio de reparto",["objective"]="Vence las dos próximas ciegas jugadas con al menos tres Jokers en cada victoria, sin conservar en la segunda ninguno de los Jokers físicos presentes en la primera.",["reward"]="Un Mega Buffoon Pack vanilla.",["failure"]="Perder, llegar a una victoria con menos de tres Jokers o repetir una identidad física del primer reparto en la segunda victoria."},["en"]={["name"]="Recasting",["objective"]="Win the next two played Blinds with at least three Jokers each. None of the physical Jokers from the first victory may remain at the second.",["reward"]="One vanilla Mega Buffoon Pack.",["failure"]="You lose, finish with fewer than three Jokers, or keep any Joker from the first cast."}},["embargo"]={["es"]={["name"]="Embargo",["objective"]="Vence las tres próximas ciegas jugadas sin gastar dinero en compras ni rerolls desde que aceptas.",["reward"]="Coupon Tag vanilla para la próxima tienda compatible.",["failure"]="Cualquier compra o reroll pagado antes de la tercera victoria, o perder la run."},["en"]={["name"]="Embargo",["objective"]="Win the next three played Blinds without paying for any purchase or reroll after acceptance. Free purchases and sales are allowed.",["reward"]="A vanilla Coupon Tag.",["failure"]="You pay for a purchase or reroll, or lose the run."}},["no_repeat"]={["es"]={["name"]="Sin bis",["objective"]="Vence la próxima ciega jugando al menos dos manos, sin reutilizar entre ellas ningún rango que haya puntuado.",["reward"]="The Death y Strength como dos Tarot reales.",["failure"]="Repetir un rango puntuante de una mano anterior, vencer en una sola mano o perder."},["en"]={["name"]="No Repeat",["objective"]="Win the next Blind in at least two hands. A rank scored in one hand may not score in any later hand. Each hand must score at least one ranked card.",["reward"]="The Death and Strength Tarot cards, queued if slots are full.",["failure"]="You reuse a scored rank across hands, win in one hand, score only rankless cards, or lose."}},["cash_register"]={["es"]={["name"]="Caja registradora",["objective"]="Gana al menos $12 con habilidades nativas de playing cards durante la próxima ciega y véncela.",["reward"]="Talisman y The Magician reales.",["failure"]="Perder o terminar la ciega sin alcanzar $12 de esas cartas."},["en"]={["name"]="Cash Register",["objective"]="Earn at least $12 from native playing-card abilities in the next Blind, including end-of-round Gold, and win.",["reward"]="Talisman and The Magician, queued if slots are full.",["failure"]="You lose or finish after playing-card payouts below $12. Joker money, sales and converted Tithe money do not count."}},["debut"]={["es"]={["name"]="Puesta de largo",["objective"]="Elige al aceptar una poker hand que aún no hayas jugado en la run y vence el próximo Boss con ella.",["reward"]="Tres copias del Planet vanilla correspondiente a la mano elegida.",["failure"]="Jugar ese tipo antes del Boss, ganar el Boss con otro tipo o perder."},["en"]={["name"]="Debut",["objective"]="Choose a visible poker hand never played this run. Do not play it before the next Boss, then beat that Boss with it.",["reward"]="Three real Planet cards for the chosen hand, queued if slots are full.",["failure"]="You play the chosen hand before the Boss, beat the Boss with another hand, or lose."}},["back_row"]={["es"]={["name"]="Última fila",["objective"]="Al comenzar la próxima ciega se señalan sus tres cartas inferiores: puntúa al menos una de ellas y vence.",["reward"]="Cryptid vanilla.",["failure"]="Perder, ganar sin puntuar ningún objetivo o destruir los tres objetivos antes de puntuar alguno."},["en"]={["name"]="Back Row",["objective"]="The next Blind marks the three cards at the bottom of your shuffled deck. Score at least one marked physical card and win.",["reward"]="One vanilla Cryptid.",["failure"]="You lose, win without scoring a target, or destroy all three targets before scoring one."}},["domino_effect"]={["es"]={["name"]="Efecto dominó",["objective"]="En la próxima ciega, consigue que una misma carta física puntúe seis veces en una mano y vence la ciega.",["reward"]="Temporary Multiplier: X1.75 Mult durante las tres próximas manos reales.",["failure"]="Perder o ganar sin haber conseguido esas seis activaciones."},["en"]={["name"]="Domino Effect",["objective"]="In the next Blind, make one physical card score six times in a single hand, then win. The original activation counts.",["reward"]="X1.75 Mult for your next three real hands.",["failure"]="You lose or win without reaching six activations on one card in one hand."}},["administrative_silence"]={["es"]={["name"]="Silencio administrativo",["objective"]="Tus Jokers quedan debuffados durante la próxima ciega; véncela.",["reward"]="Negative Tag vanilla.",["failure"]="Perder esa ciega."},["en"]={["name"]="Administrative Silence",["objective"]="All your Jokers are natively debuffed for the next Blind, including newly acquired Jokers. Win that Blind.",["reward"]="A vanilla Negative Tag.",["failure"]="You lose that Blind."}},["protected_witnesses"]={["es"]={["name"]="Testigos protegidos",["objective"]="Al robar la primera mano de la próxima ciega, elige tres cartas y vence sin jugarlas, descartarlas ni destruirlas.",["reward"]="The Chariot y Trance reales.",["failure"]="Mover cualquiera de las tres fuera de la mano por jugar, descartar o destruir, o perder."},["en"]={["name"]="Protected Witnesses",["objective"]="Choose three cards from the first draw of the next Blind. Win without playing, discarding or destroying them. Forced discards also fail.",["reward"]="The Chariot and Trance, queued if slots are full.",["failure"]="You play, discard or destroy any witness, or lose."}},["seed_capital"]={["es"]={["name"]="Capital semilla",["objective"]="Compra un Joker después de aceptar y revéndelo por al menos $8 más de lo que pagaste antes de terminar el segundo Boss desde la aceptación.",["reward"]="Elegir un Contraband real entre tres candidatos elegibles distintos.",["failure"]="Llegar a ese segundo Boss sin una operación válida o perder."},["en"]={["name"]="Seed Capital",["objective"]="Buy a Joker after acceptance and resell that physical Joker for at least $8 more than its purchase price before the second Boss ends.",["reward"]="Choose one real Contraband from three distinct eligible candidates; the choice stays pending if slots are full.",["failure"]="You reach the second Boss without a qualifying sale, or lose. Gifts and leased Jokers do not count."}}}
